<?php namespace App\Database; use CodeIgniter\Database\MigrationRunner; use Throwable; class TestMigrationRunner extends MigrationRunner { protected function migrate($direction, $migration): bool { try { return parent::migrate($direction, $migration); } catch (Throwable $e) { if ($this->db->DBDriver === "SQLite3" && (str_contains($e->getMessage(), 'near "CONSTRAINT": syntax error') || str_contains($e->getMessage(), 'near "FOREIGN": syntax error') || str_contains($e->getMessage(), 'DROP COLUMN'))) { return true; } throw $e; } } }
